func probeOnlyAC(t *testing.T, cc *ClientConn) *addrConn {
	t.Helper()
	cc.mu.Lock()
	defer cc.mu.Unlock()
	for ac := range cc.conns {
		return ac
	}
	t.Fatal("no addrConn")
	return nil
}

// Connecting subchannel: does updateAddrs return with ac.mu still locked?
func TestZZProbeUpdateAddrsConnecting(t *testing.T) {
	lis, err := net.Listen("tcp", "localhost:0")
	if err != nil {
		t.Fatal(err)
	}
	defer lis.Close()
	accepted := make(chan struct{})
	go func() {
		c, err := lis.Accept()
		if err != nil {
			return
		}
		close(accepted)
		defer c.Close()
		time.Sleep(10 * time.Second)
	}()
	rb := manual.NewBuilderWithScheme("probe")
	rb.InitialState(resolver.State{Addresses: []resolver.Address{{Addr: lis.Addr().String()}}})
	cc, err := Dial("probe:///x", WithTransportCredentials(insecure.NewCredentials()), WithResolvers(rb))
	if err != nil {
		t.Fatal(err)
	}
	defer cc.Close()
	select {
	case <-accepted:
	case <-time.After(5 * time.Second):
		t.Fatal("no dial")
	}
	ac := probeOnlyAC(t, cc)

	defer runtime.GOMAXPROCS(runtime.GOMAXPROCS(1))
	ac.updateAddrs([]resolver.Address{{Addr: "localhost:1"}})
	held := !ac.mu.TryLock()
	if !held {
		ac.mu.Unlock()
	}
	t.Logf("PROBE connecting: ac.mu still locked when updateAddrs returned = %v", held)
}

// Ready subchannel: does the deferred GracefulClose->onClose block on ac.mu?
func TestZZProbeUpdateAddrsReady(t *testing.T) {
	lis, err := net.Listen("tcp", "localhost:0")
	if err != nil {
		t.Fatal(err)
	}
	s := NewServer()
	go s.Serve(lis)
	defer s.Stop()
	rb := manual.NewBuilderWithScheme("probe")
	rb.InitialState(resolver.State{Addresses: []resolver.Address{{Addr: lis.Addr().String()}}})
	cc, err := Dial("probe:///x", WithTransportCredentials(insecure.NewCredentials()), WithResolvers(rb))
	if err != nil {
		t.Fatal(err)
	}
	defer cc.Close()
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	for st := cc.GetState(); st != connectivity.Ready; st = cc.GetState() {
		if !cc.WaitForStateChange(ctx, st) {
			t.Fatalf("never READY, state %v", st)
		}
	}
	ac := probeOnlyAC(t, cc)

	defer runtime.GOMAXPROCS(runtime.GOMAXPROCS(1))
	runtime.SetBlockProfileRate(1)
	ac.updateAddrs([]resolver.Address{{Addr: "localhost:1"}})
	runtime.SetBlockProfileRate(0)

	var buf bytes.Buffer
	pprof.Lookup("block").WriteTo(&buf, 1)
	found := false
	for _, rec := range strings.Split(buf.String(), "\n\n") {
		if strings.Contains(rec, "GracefulClose") && strings.Contains(rec, "updateAddrs") && strings.Contains(rec, "createTransport.func1") {
			found = true
			t.Logf("PROBE ready: blocked stack:\n%s", rec)
		}
	}
	t.Logf("PROBE ready: deferred GracefulClose->onClose blocked on ac.mu inside updateAddrs = %v", found)
}
EOF
