// zzIdleBal creates one SubConn and never connects it, leaving it IDLE.
type zzIdleBal struct {
	cc balancer.ClientConn
	sc balancer.SubConn
}

func (b *zzIdleBal) UpdateClientConnState(s balancer.ClientConnState) error {
	if b.sc == nil {
		b.sc, _ = b.cc.NewSubConn(s.ResolverState.Addresses, balancer.NewSubConnOptions{StateListener: func(balancer.SubConnState) {}})
	}
	return nil
}
func (b *zzIdleBal) ResolverError(error)                                         {}
func (b *zzIdleBal) UpdateSubConnState(balancer.SubConn, balancer.SubConnState) {}
func (b *zzIdleBal) Close()                                                      {}

type zzIdleBB struct{}

func (zzIdleBB) Build(cc balancer.ClientConn, _ balancer.BuildOptions) balancer.Balancer {
	return &zzIdleBal{cc: cc}
}
func (zzIdleBB) Name() string { return "zz_idle" }

func init() { balancer.Register(zzIdleBB{}) }

// N goroutines call ac.connect() on an IDLE addrConn at once; exactly one
// connection may reach the listener.
func TestZZStressConcurrentConnect(t *testing.T) {
	const iters, racers = 300, 8
	bad := 0
	for i := 0; i < iters; i++ {
		lis, err := net.Listen("tcp", "localhost:0")
		if err != nil {
			t.Fatal(err)
		}
		var accepts atomic.Int32
		go func() {
			for {
				c, err := lis.Accept()
				if err != nil {
					return
				}
				accepts.Add(1)
				defer c.Close()
			}
		}()
		rb := manual.NewBuilderWithScheme("zzstress")
		rb.InitialState(resolver.State{Addresses: []resolver.Address{{Addr: lis.Addr().String()}}})
		cc, err := Dial("zzstress:///x", WithTransportCredentials(insecure.NewCredentials()), WithResolvers(rb),
			WithDefaultServiceConfig(`{"loadBalancingConfig": [{"zz_idle":{}}]}`))
		if err != nil {
			t.Fatal(err)
		}
		var ac *addrConn
		for deadline := time.Now().Add(5 * time.Second); ac == nil; {
			cc.mu.Lock()
			for a := range cc.conns {
				ac = a
			}
			cc.mu.Unlock()
			if ac == nil {
				if time.Now().After(deadline) {
					t.Fatal("no addrConn")
				}
				time.Sleep(time.Millisecond)
			}
		}
		start := make(chan struct{})
		var wg sync.WaitGroup
		for r := 0; r < racers; r++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				<-start
				go ac.connect() // as acBalancerWrapper.Connect does
			}()
		}
		close(start)
		wg.Wait()
		time.Sleep(15 * time.Millisecond)
		if n := accepts.Load(); n != 1 {
			bad++
		}
		cc.Close()
		lis.Close()
	}
	t.Logf("STRESS: iterations with != 1 dial: %d of %d", bad, iters)
}
